#define main old_main
#include "s61_binary_hyperplane_kernel_peel_20261102.cpp"
#undef main
int main(int argc,char**argv){assert(argc==3);ifstream in(argv[1]);ofstream out(argv[2]);assert(in&&out);fmpq_mpoly_ctx_init(ctx,3,ORD_LEX);{int n,m;in>>n>>m;vector<vector<Poly>>A(n,vector<Poly>(m));for(auto&r:A)for(auto&p:r)read(in,p,2);auto start=chrono::steady_clock::now();for(int round=0;round<2;round++)for(int axis=0;axis<2;axis++){int outer=axis?m:n,inner=axis?n:m;for(int i=0;i<outer;i++){Poly g,h,q;for(int j=0;j<inner;j++){auto&p=axis?A[j][i]:A[i][j];assert(fmpq_mpoly_gcd(h.p,g.p,p.p,ctx));g=h;if(fmpq_mpoly_is_fmpq(g.p,ctx)&&!fmpq_mpoly_is_zero(g.p,ctx))break;}if(fmpq_mpoly_is_zero(g.p,ctx))continue;for(int j=0;j<inner;j++){auto&p=axis?A[j][i]:A[i][j];assert(fmpq_mpoly_divides(q.p,p.p,g.p,ctx));p=q;}fmpq_t c;fmpq_init(c);bool ok=false;for(int j=0;j<inner;j++){auto&p=axis?A[j][i]:A[i][j];if(!fmpq_mpoly_is_zero(p.p,ctx)){fmpq_mpoly_get_term_coeff_fmpq(c,p.p,0,ctx);ok=true;break;}}assert(ok);for(int j=0;j<inner;j++){auto&p=axis?A[j][i]:A[i][j];fmpq_mpoly_scalar_div_fmpq(p.p,p.p,c,ctx);}fmpq_clear(c);}long terms=0;for(auto&r:A)for(auto&p:r)terms+=fmpq_mpoly_length(p.p,ctx);cerr<<"PRIMITIVE "<<round<<' '<<axis<<" TERMS "<<terms<<" SEC "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}out<<n<<' '<<m<<'\n';for(auto&r:A)for(auto&p:r)write(out,p,2);out.flush();assert(out.good());}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
